import { Metadata } from "next";
import RateListClient from "./RateListClient";

const CANONICAL = "https://www.trayago.in/rate-list";

export const metadata: Metadata = {
  title: "IRCTC Station Rate List & Standard Food Prices | Trayago",
  description:
    "Official Indian Railways and IRCTC approved catering rate list. Check standard menu prices for tea, meals, packaged water, and breakfast at railway stations.",
  alternates: {
    canonical: CANONICAL,
  },
  keywords:
    "IRCTC rate list, railway food price, train food price list, railway tea price, Rail Neer price, IRCTC meal price list, train catering charges",
  robots: {
    index: true,
    follow: true,
  },
  openGraph: {
    type: "website",
    title: "IRCTC Station Rate List & Standard Food Prices | Trayago",
    description:
      "Official Indian Railways and IRCTC approved catering rate list for station food, meals, tea, and beverages.",
    url: CANONICAL,
    siteName: "Trayago",
  },
  twitter: {
    card: "summary_large_image",
    title: "IRCTC Station Rate List & Standard Food Prices",
    description:
      "Official approved catering prices for tea, water, breakfast, and meals at Indian railway stations.",
  },
};

export default function RateListPage() {
  const breadcrumbJsonLd = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: "https://www.trayago.in" },
      { "@type": "ListItem", position: 2, name: "Station Rate List", item: CANONICAL },
    ],
  };

  const webPageJsonLd = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    name: "IRCTC Station Rate List & Standard Food Prices",
    url: CANONICAL,
    description:
      "Official Indian Railways and IRCTC approved catering rate list. Check standard menu prices for tea, meals, packaged water, and breakfast at railway stations.",
    isPartOf: {
      "@type": "WebSite",
      name: "Trayago",
      url: "https://www.trayago.in",
    },
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbJsonLd) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(webPageJsonLd) }}
      />
      <RateListClient />
    </>
  );
}
